public class HardwareController {
    static {
        System.loadLibrary("hw-interface");
    }

    // Declare native method
    public native int readSensorData(byte[] buffer);

    public static void main(String[] args) {
        HardwareController controller = new HardwareController();
        byte[] data = new byte[1024];
        int bytesRead = controller.readSensorData(data);
        System.out.println("Read " + bytesRead + " bytes from hardware.");
    }
}
